           (-l[0]**2*(l[1]**2 + l[2]**2) + l[1]*l[2]*(-3*l[0]*l[1]*np.tan(g[1]) - 3*l[0]*l[2]*np.tan(g[0]) + l[1]*l[2] - l[1]*l[2]/np.cos(g[1])**2 - l[1]*l[2]/np.cos(g[0])**2))/(36*l[0]*l[1]*l[2]),
